// log_call — Validate Input
// Expected body: { business_id, caller_number, intent, outcome,
//                  call_summary, booking_id?, duration_seconds? }
//
// intent/outcome must land on the exact values the CHECK constraints on
// `calls` allow (supabase/migrations/0001_init.sql + 0002_multi_business.sql).
// A voice agent won't reliably send exact casing, so close variants are
// mapped -- but anything not on the list is still an error, never guessed.
const INTENTS = {
  faq: 'FAQ', question: 'FAQ', info: 'Info', information: 'Info',
  booking: 'Booking', book: 'Booking', appointment: 'Booking',
  callback: 'Callback', 'callback request': 'Callback', lead: 'Callback',
  transfer: 'Transfer', human: 'Transfer',
};
const OUTCOMES = {
  'faq answered': 'FAQ Answered', faq_answered: 'FAQ Answered', answered: 'FAQ Answered',
  'info provided': 'Info Provided', info_provided: 'Info Provided', info: 'Info Provided',
  booked: 'Booked', booking: 'Booked',
  'callback requested': 'Callback Requested', callback_requested: 'Callback Requested', callback: 'Callback Requested',
  transferred: 'Transferred', transfer: 'Transferred',
  'no match': 'No Match', no_match: 'No Match', nomatch: 'No Match',
};

const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const callerNumber = String(body.caller_number ?? body.from ?? '').trim();
const rawIntent = String(body.intent ?? '').trim();
const rawOutcome = String(body.outcome ?? '').trim();
const summary = String(body.call_summary ?? body.summary ?? '').trim() || null;
const bookingId = String(body.booking_id ?? '').trim() || null;

const rawDuration = body.duration_seconds;
const hasDuration = rawDuration !== undefined && rawDuration !== null && rawDuration !== '';
const durationSeconds = hasDuration ? Number(rawDuration) : null;

const intent = INTENTS[rawIntent.toLowerCase()] || null;
const outcome = OUTCOMES[rawOutcome.toLowerCase()] || null;

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!callerNumber) errors.push('caller_number is required');

if (!rawIntent) {
  errors.push('intent is required');
} else if (!intent) {
  errors.push('intent must be one of: FAQ, Booking, Transfer, Info, Callback');
}

if (!rawOutcome) {
  errors.push('outcome is required');
} else if (!outcome) {
  errors.push('outcome must be one of: FAQ Answered, Booked, Transferred, No Match, Info Provided, Callback Requested');
}

if (hasDuration && (!Number.isFinite(durationSeconds) || durationSeconds < 0)) {
  errors.push('duration_seconds must be a non-negative number');
}

if (bookingId && !/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(bookingId)) {
  errors.push('booking_id must be a UUID');
}

const endedAt = DateTime.now();
const startedAt =
  Number.isFinite(durationSeconds) && durationSeconds > 0
    ? endedAt.minus({ seconds: durationSeconds })
    : endedAt;

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    caller_number: callerNumber,
    intent,
    outcome,
    call_summary: summary,
    booking_id: bookingId,
    duration_seconds: Number.isFinite(durationSeconds) ? durationSeconds : null,
    started_at: startedAt.toISO(),
    ended_at: endedAt.toISO(),
  },
}];

// Normalize Business
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{ json: { business_found: !!row, business_id: row ? row.id : null } }];

// log_call — Normalize Call
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{ json: { logged: !!row, call_id: row ? row.id : null } }];

// log_call — Build Response
// Fed by three branches (no booking to link, link succeeded, link
// failed), so call_id is read from the node that always has it. Failing
// to attach the call to its appointment does not un-log the call: the
// call row is the audit record and exists either way. The booking-link
// PATCH above is scoped to this same business_id, so a booking_id from a
// different business can never be linked here.
const call = $('Normalize Call').first().json;
const input = $('Validate Input').first().json;

let bookingLink = 'not_requested';
if (input.booking_id) {
  const item = $input.first();
  const linkFailed = !!(item && item.json && item.json.error);
  const linkedRow = !!(item && item.json && item.json.id);
  bookingLink = linkFailed ? 'failed' : linkedRow ? 'linked' : 'not_found';
}

return [{
  json: {
    status: 'logged',
    logged: true,
    call_id: call.call_id,
    business_id: input.business_id_input,
    caller_number: input.caller_number,
    intent: input.intent,
    outcome: input.outcome,
    booking_id: input.booking_id,
    booking_link: bookingLink,
  },
}];
